#!/usr/bin/env python3
import os
import re
import pandas as pd
import pytesseract
from PIL import Image
from datetime import datetime
import openpyxl

# Directory containing receipt images
img_dir = "/app/workspace/dataset/img"
output_file = "/app/workspace/stat_ocr.xlsx"

def extract_text_from_image(image_path):
    """Extract text from receipt image using Tesseract OCR."""
    try:
        img = Image.open(image_path)
        text = pytesseract.image_to_string(img)
        return text
    except Exception as e:
        print(f"Error processing {image_path}: {e}")
        return ""

def extract_date(text):
    """Extract date from receipt text in ISO format (YYYY-MM-DD)."""
    # Common date patterns
    patterns = [
        r'(\d{2})[/-](\d{2})[/-](\d{4})',  # DD/MM/YYYY or DD-MM-YYYY
        r'(\d{4})[/-](\d{2})[/-](\d{2})',  # YYYY/MM/DD or YYYY-MM-DD
        r'(\d{2})[/-](\d{2})[/-](\d{2})',  # YY/MM/DD or YY-MM-DD
    ]

    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            groups = match.groups()
            try:
                if len(groups[0]) == 4:  # YYYY format
                    year, month, day = groups
                    return f"{year}-{month:0>2}-{day:0>2}"
                elif len(groups[2]) == 4:  # DD/MM/YYYY format
                    day, month, year = groups
                    return f"{year}-{month:0>2}-{day:0>2}"
                else:  # YY/MM/DD format
                    year, month, day = groups
                    year = int(year)
                    if year < 50:
                        year += 2000
                    else:
                        year += 1900
                    return f"{year}-{month:0>2}-{day:0>2}"
            except:
                continue

    return None

def extract_total_amount(text):
    """Extract total amount from receipt text."""
    lines = text.split('\n')

    # Priority 1: GRAND TOTAL
    for i, line in enumerate(lines):
        if 'GRAND TOTAL' in line.upper():
            if not any(kw in line.upper() for kw in ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']):
                amount = extract_amount_from_line(line)
                if amount:
                    return amount
                # Try next line as fallback
                if i + 1 < len(lines):
                    amount = extract_amount_from_line(lines[i + 1])
                    if amount:
                        return amount

    # Priority 2: TOTAL RM or TOTAL: RM
    for i, line in enumerate(lines):
        if ('TOTAL RM' in line.upper() or 'TOTAL: RM' in line.upper()) and not any(kw in line.upper() for kw in ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']):
            amount = extract_amount_from_line(line)
            if amount:
                return amount
            # Try next line as fallback
            if i + 1 < len(lines):
                amount = extract_amount_from_line(lines[i + 1])
                if amount:
                    return amount

    # Priority 3: TOTAL AMOUNT
    for i, line in enumerate(lines):
        if 'TOTAL AMOUNT' in line.upper() and not any(kw in line.upper() for kw in ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']):
            amount = extract_amount_from_line(line)
            if amount:
                return amount
            # Try next line as fallback
            if i + 1 < len(lines):
                amount = extract_amount_from_line(lines[i + 1])
                if amount:
                    return amount

    # Priority 4: TOTAL, AMOUNT, TOTAL DUE, AMOUNT DUE, BALANCE DUE, NETT TOTAL, NET TOTAL
    priority_keywords = ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT']

    for keyword in priority_keywords:
        for i, line in enumerate(lines):
            if keyword in line.upper() and not any(kw in line.upper() for kw in ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']):
                amount = extract_amount_from_line(line)
                if amount:
                    return amount
                # Try next line as fallback
                if i + 1 < len(lines):
                    amount = extract_amount_from_line(lines[i + 1])
                    if amount:
                        return amount

    return None

def extract_amount_from_line(line):
    """Extract monetary amount from a line of text."""
    # Look for patterns like: 123.45 or 1,234.56
    pattern = r'[\d,]+\.?\d{0,2}(?=\D|$)'
    matches = re.findall(pattern, line)

    if matches:
        # Get the last match (usually the amount)
        amount_str = matches[-1]
        # Remove commas
        amount_str = amount_str.replace(',', '')

        try:
            amount = float(amount_str)
            # Format with exactly 2 decimal places
            return f"{amount:.2f}"
        except:
            return None

    return None

def process_receipts():
    """Process all receipt images and extract data."""
    data = []

    # Get all image files and sort by filename
    image_files = sorted([f for f in os.listdir(img_dir) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.gif', '.bmp'))])

    for filename in image_files:
        image_path = os.path.join(img_dir, filename)
        print(f"Processing {filename}...")

        text = extract_text_from_image(image_path)
        date = extract_date(text)
        total_amount = extract_total_amount(text)

        data.append({
            'filename': filename,
            'date': date,
            'total_amount': total_amount
        })

        print(f"  Date: {date}, Total: {total_amount}")

    # Create DataFrame
    df = pd.DataFrame(data)

    # Write to Excel
    with pd.ExcelWriter(output_file, engine='openpyxl') as writer:
        df.to_excel(writer, sheet_name='results', index=False)

    print(f"\nData written to {output_file}")

if __name__ == "__main__":
    process_receipts()

