    # Common date patterns - search for all matches
    pattern = r'(\d{1,4})[/-](\d{1,2})[/-](\d{1,4})'

    matches = re.findall(pattern, text)

    for groups in matches:
        g1, g2, g3 = groups
        try:
            # Convert to integers
            num1, num2, num3 = int(g1), int(g2), int(g3)

            # Determine format based on the range of numbers
            if num1 >= 1900:  # YYYY/MM/DD format
                year, month, day = num1, num2, num3
            elif num3 >= 1900:  # DD/MM/YYYY format
                day, month, year = num1, num2, num3
            elif num1 > 31:  # YYYY/MM/DD (with 2-digit year impossible, so must be 4-digit year)
                year, month, day = num1, num2, num3
            elif num3 > 31:  # DD/MM/YYYY format
                day, month, year = num1, num2, num3
            else:
                # Ambiguous, try both interpretations
                # Try DD/MM/YY format first (more common in receipts)
                if 1 <= num1 <= 31 and 1 <= num2 <= 12:
                    day, month = num1, num2
                    year = num3
