                year, month, day = num1, num2, num3
            elif num3 > 31:  # DD/MM/YYYY format
                day, month, year = num1, num2, num3
            else:
                # Ambiguous, try both interpretations
                # Try DD/MM/YY format first (more common in receipts)
                if 1 <= num1 <= 31 and 1 <= num2 <= 12:
