#!/usr/bin/env python3
import os
import re
import pandas as pd
import pytesseract
from PIL import Image
from datetime import datetime
import openpyxl

# Directory containing receipt images
img_dir = "/app/workspace/dataset/img"
output_file = "/app/workspace/stat_ocr.xlsx"

def extract_text_from_image(image_path):
    """Extract text from receipt image using Tesseract OCR."""
    try:
        img = Image.open(image_path)
        text = pytesseract.image_to_string(img)
        return text
    except Exception as e:
        print(f"Error processing {image_path}: {e}")
        return ""

def extract_date(text):
    """Extract date from receipt text in ISO format (YYYY-MM-DD)."""
    # Pattern 1: With separators (/, -)
    pattern1 = r'(\d{1,4})[/-](\d{1,2})[/-](\d{1,4})'
    matches = re.findall(pattern1, text)

    for groups in matches:
        result = parse_date_triple(groups)
        if result:
            return result

    # Pattern 2: Without separators - look for 6 or 8 digit sequences near "Date" keyword
    # e.g., "Date: 20032018" (DDMMYYYY) or "Date: 2032018" (DMMYYYY with possible OCR error)
    pattern2 = r'Date\s*[:=]\s*(\d{6,8})'
    matches2 = re.findall(pattern2, text, re.IGNORECASE)

    for date_str in matches2:
        # Try different interpretations
        # Most likely: DDMMYYYY
        if len(date_str) == 8:
            day, month, year = int(date_str[0:2]), int(date_str[2:4]), int(date_str[4:8])
            if 1 <= month <= 12 and 1 <= day <= 31 and 1900 <= year <= 2100:
                return f"{year:04d}-{month:02d}-{day:02d}"

        # Try DMMYYYY (7 digits, day might be single digit)
        if len(date_str) == 7:
            day, month, year = int(date_str[0]), int(date_str[1:3]), int(date_str[3:7])
            if 1 <= month <= 12 and 1 <= day <= 31 and 1900 <= year <= 2100:
                return f"{year:04d}-{month:02d}-{day:02d}"

        # Try DDMYYYY (7 digits, month might be single digit)
        if len(date_str) == 7:
            day, month, year = int(date_str[0:2]), int(date_str[2]), int(date_str[3:7])
            if 1 <= month <= 12 and 1 <= day <= 31 and 1900 <= year <= 2100:
                return f"{year:04d}-{month:02d}-{day:02d}"

        # Try DMYYYY (6 digits)
        if len(date_str) == 6:
            day, month, year = int(date_str[0]), int(date_str[1]), int(date_str[2:6])
            if 1 <= month <= 12 and 1 <= day <= 31 and 1900 <= year <= 2100:
                return f"{year:04d}-{month:02d}-{day:02d}"

    return None

def parse_date_triple(groups):
    """Parse a date from three number groups."""
    try:
        g1, g2, g3 = groups
        # Convert to integers
        num1, num2, num3 = int(g1), int(g2), int(g3)

        # Determine format based on the range of numbers
        if num1 >= 1900:  # YYYY/MM/DD format
            year, month, day = num1, num2, num3
        elif num3 >= 1900:  # DD/MM/YYYY format
            day, month, year = num1, num2, num3
        elif num1 > 31:  # YYYY/MM/DD (with 2-digit year impossible, so must be 4-digit year)
            year, month, day = num1, num2, num3
        elif num3 > 31:  # DD/MM/YYYY format
            day, month, year = num1, num2, num3
        else:
            # Ambiguous, try both interpretations
            # Try DD/MM/YY format first (more common in receipts)
            if 1 <= num1 <= 31 and 1 <= num2 <= 12:
                day, month = num1, num2
                year = num3
                if year < 100:
                    year += 2000 if year < 50 else 1900
            elif 1 <= num2 <= 31 and 1 <= num1 <= 12:
                month, day = num1, num2
                year = num3
                if year < 100:
                    year += 2000 if year < 50 else 1900
            else:
                return None

        # Validate the date
        if 1 <= month <= 12 and 1 <= day <= 31 and 1900 <= year <= 2100:
            return f"{year:04d}-{month:02d}-{day:02d}"
    except:
        pass

    return None

