        except:
            return None

    return None

def process_receipts():
    """Process all receipt images and extract data."""
    data = []

    # Get all image files and sort by filename
    image_files = sorted([f for f in os.listdir(img_dir) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.gif', '.bmp'))])

