            amount = float(amount_str)
            # Format with exactly 2 decimal places
            return f"{amount:.2f}"
        except:
            return None

    return None

def process_receipts():
    """Process all receipt images and extract data."""
    data = []

    # Get all image files and sort by filename
    image_files = sorted([f for f in os.listdir(img_dir) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.gif', '.bmp'))])

    for filename in image_files:
        image_path = os.path.join(img_dir, filename)
        print(f"Processing {filename}...")

        text = extract_text_from_image(image_path)
        date = extract_date(text)
        total_amount = extract_total_amount(text)

        data.append({
            'filename': filename,
            'date': date,
            'total_amount': total_amount
        })

        print(f"  Date: {date}, Total: {total_amount}")

    # Create DataFrame
    df = pd.DataFrame(data)

    # Write to Excel
    with pd.ExcelWriter(output_file, engine='openpyxl') as writer:
        df.to_excel(writer, sheet_name='results', index=False)

    print(f"\nData written to {output_file}")

if __name__ == "__main__":
    process_receipts()
